const count = Number(tobub.params.count);

await tobub.atoms.navigate({ url: 'https://www.xiaohongshu.com', waitUntil: 'domcontentloaded' })

await tobub.atoms.waitFor([500, 2000]);

await tobub.atoms.fill({ selector: 'textarea#search-input-in-feeds', value: searchKey });

await tobub.atoms.press({ key: 'Enter' });

await tobub.atoms.waitFor([1500, 3000]);

await tobub.atoms.click({
  selector: '.xhs-ai-chat-header button svg.reds-icon'
});

await tobub.atoms.waitFor([1500, 2000]);

await tobub.atoms.hover({ selector: 'div.filter span:has-text("筛选")' ,lingerTime: [500, 900]});

await tobub.atoms.waitFor([1500, 2000]);

await tobub.atoms.click({
  selector: 'div.filter-panel span:has-text("最新")',
});

const records = [];
let scans = 0;
let noNewDataCount = 0

for (let i = 0; i < 999 ; i++) {
  scans++;
  await tobub.atoms.waitFor([1000, 2600]);
  await tobub.atoms.scroll({ mode: "viewport", distance: tobub.utils.randInt(390, 1200), steps: tobub.utils.randInt(3, 15), stepPauseRange: [10, 25] });
  const list = await tobub.adapter.extract("search", { scan: { mode: "append" } });
  for (const record of list.records) {
    if (records.length >= count) break;
    records.push(record);
    const fields = record.fields ?? {};
    const externalId = String(record.id || fields.id || "");
    if (!externalId) continue;
    await tobub.db.saveContent({
      platform: "Redbook",
      contentType: "article",
      externalId,
      title: fields.title ?? externalId,
      summary: fields.author ?? "",
      url: "https://www.xiaohongshu.com" + fields.link,
      metadata: {
        thumb: fields.thumb ?? "",
        title: fields.title ?? "",
        like: fields.like ?? "",
        author: fields.author ?? "",
        time: fields.time ?? ""
      },
      rawData: fields
    });
